"""Source-bounded Norwegian research-film scripts. Human review required before publication."""
SOURCES={
 'imas':'https://aleximas.substack.com/p/has-ai-impacted-the-labor-market',
 'stanford':'https://digitaleconomy.stanford.edu/publication/canaries-in-the-coal-mine-six-facts-about-the-recent-employment-effects-of-artificial-intelligence/',
 'yale':'https://budgetlab.yale.edu/research/tracking-impact-ai-labor-market',
 'anthropic':'https://www.anthropic.com/institute/econ-scenarios',
 'ssb':'https://www.ssb.no/nasjonalregnskap-og-konjunkturer/okonomiske-analyser/okonomiske-analyser-3-2026/_/attachment/inline/d4d8d116-010f-47dd-9199-a310afb82b0d:3cb1168f84743db8b67fdac3f2ebdc7e7eed2773/OA2026-3.pdf#page=36',
 'model':'https://www-cdn.anthropic.com/files/4zrzovbb/website/cf58f84d46a4a76bf5a5b039ac695fba6b80041c.pdf'}
FILMS={
'imas':[
 ('research_open','Har KI endret arbeidsmarkedet?', 'Alex Imas og Jacob Schaal har gått gjennom forskningen om KI og arbeidsmarkedet. Hovedbildet er blandet. Det finnes tegn til svakere rekruttering av unge i utsatte kontoryrker, men ingen tydelig, bred jobbkrise.', ['imas']),
 ('flow','Nyansettelser og ansatte er ulike mål','Se for deg en bedrift som har ansatte, men som slutter å fylle ledige stillinger. I begynnelsen endrer antallet ansatte seg lite. Likevel møter jobbsøkere færre muligheter. Stillingsannonser og nyansettelser kan derfor varsle endringer tidligere enn antall ansatte samlet.', ['imas']),
 ('us','Et tydelig amerikansk mønster','Stanford-forskerne bruker amerikanske lønnsdata. I deres oppdatering til juni 2026 ligger sysselsettingen blant personer fra tjueto til tjuefem år i yrker som er utsatt for KI nitten prosent under banen vi sammenligner med. Den banen viser hvordan gruppen ville utviklet seg om den hadde fulgt mindre eksponerte jevnaldrende. Dette betyr ikke at nitten prosent har fått sparken. Forskjellen oppstår særlig gjennom færre nyansettelser. Forskerne beskriver mønsteret som et tidlig varselsignal, ikke som et sikkert mål på virkningen av KI. Noen forskjeller startet tidligere, og utdanningskontroller demper utslaget.', ['stanford']),
 ('nordic','Resultatene varierer mellom land','Gjennomgangen finner ikke det samme brede mønsteret i nordiske data for hele befolkningen. Norske og finske studier gir svakere støtte til at unge i yrker som er utsatt for KI taper generelt. Et fall blant unge utviklere kan eksistere samtidig som forskjellen mellom alle høyt og lavt eksponerte yrker er liten.', ['imas']),
 ('causes','Flere mulige forklaringer','Årsaken er omstridt. Hjemmekontor, renteøkninger og korreksjon etter pandemien kan påvirke de samme yrkene som KI. Forskningen forsøker å skille forklaringene, men resultatene avhenger av data og metode. Eksponering beskriver hva teknologien kan gjøre. Det er ikke et mål på hvor mye den faktisk brukes.', ['imas']),
 ('aggregate','Hva viser arbeidsmarkedet samlet?','Yales Budget Lab følger også utviklingen. I oppdateringen fra fjortende oktober 2026 finner de ikke et tydelig KI-mønster i sammensetningen av yrker. Bruksmålene deres henger heller ikke sammen med endringer i hvor mange som har jobb eller er ledige. Dette er funn om dagens data, ikke et løfte om framtiden. En bedrift kan spare tid på en oppgave uten å redusere bemanningen, for eksempel hvis den bruker tiden til flere leveranser. Slike muligheter gjør det nødvendig å undersøke hva som faktisk skjer med jobber og arbeidstid.', ['yale']),
 ],
'anthropic':[
 ('scenario_open','Mulige økonomier i 2030','Anthropics modell viser mulige framtider for USA fram mot 2030, der antakelsene om KI bestemmer utslagene for produksjon, lønn og jobber. Scenarioene er ikke prognoser. Forskerne har ikke gitt dem sannsynligheter.', ['model']),
 ('task_machine','Fra oppgaver til økonomi','Start med arbeidsoppgavene. KI kan hjelpe en ansatt, overta en oppgave eller føre til nye oppgaver. Andre oppgaver forblir uendret. Det avgjørende er både hva KI kan gjøre og hvor mye bedrifter faktisk bruker teknologien. Evne og bruk er forskjellige ting.', ['anthropic']),
 ('levers','Antakelsene styrer resultatet','Modellen varierer hvor mange oppgaver KI berører, hvor utbredt bruken blir, og hvor store produktivitetsgevinstene er. Den skiller også mellom hjelp og automatisering, og tar med nye oppgaver. Så kommer arbeidsmarkedet: Hvor raskt kan en person som mister jobben finne annet arbeid?', ['anthropic']),
 ('scenario_bars','Tre scenarioer, samme sammenligning','I det moderate scenarioet er amerikansk BNP i 2030 én komma seks prosent høyere enn uten KI. I det betydelige scenarioet er forskjellen åtte komma tre prosent. I det ekstreme er den trettito komma fire prosent. Dette er forskjeller i nivå i 2030, ikke årlige vekstrater.', ['anthropic']),
 ('transition','Mer produksjon, vanskelig omstilling','En programmerer blir ikke elektriker over natten. Jobbsøking og opplæring tar tid. Derfor kan flere stå uten arbeid under omstillingen, selv om økonomien produserer mer.', ['model']),
 ('distribution','Hvem får inntektene?','Høyere BNP garanterer ikke høyere lønn for alle. I det ekstreme scenarioet går mer av inntekten til kapital. Kunnskapsarbeidernes lønn ligger under banen uten KI.', ['model']),
 ('unemployment','Ledighet i USA i 2030','Hva betyr dette for ledigheten? I det moderate scenarioet er samlet ledighet tre komma ni prosent. I det betydelige er den fire komma seks prosent. I det ekstreme er den elleve komma ni prosent. Dette er ledighetsnivåer, ikke økninger. Uten KI er nivået tre komma åtte prosent. I det ekstreme scenarioet er sytten komma ni prosent av dem som startet i kunnskapsyrker uten arbeid. Den gruppen må ikke forveksles med alle arbeidstakere.', ['model']),
 ('limits','Fra spart tid til jobber','Spart arbeidstid er ikke det samme som tapte jobber. Et generelt produktivitetsløft og automatisering av bestemte oppgaver er heller ikke samme endring. Resultatet avhenger av hvordan bedriftene bruker den sparte tiden, om etterspørselen øker, om nye oppgaver oppstår, og hvor raskt folk som mister jobben finner annet arbeid. Tallene her gjelder USA. De kan ikke overføres direkte til Norge.', ['ssb']),
 ]
}
